  function importConnectRealBatch(workspace){
    if(workspace.connectRealBatchVersion==='connect-u01-u03-v1')return;
    const batch=connectRealBatch(),course=workspace.courses.find(item=>item.id==='connect');
    if(!course)return;
    Object.assign(course,{name:'Connect — 2ª Edição',level:'Elementary • Adults',description:'Connect 2026.2 — currículo operacional com 21 Class Meetings de 2 horas pedagógicas.',pedagogicalInfo:'Primeiro lote real: Units 01-03 com Meetings 02-06, foco em Simple Past, past memories/incidents e getting around.'});
    const importedUnitIds=new Set(batch.units.map(unit=>unit.id));
    const preservedUnits=(course.units||[]).filter(unit=>!importedUnitIds.has(unit.id));
    course.units=[...batch.units,...preservedUnits];
    workspace.curricula=workspace.curricula||[];
    workspace.curricula=workspace.curricula.filter(item=>item.id!==batch.curriculum.id);
    workspace.curricula.push(batch.curriculum);
    for(const lessonId of Object.keys(batch.plans)){
      const base=batch.plans[lessonId];
      let lesson=null;
      for(const unit of course.units||[])lesson=lesson||(unit.lessons||[]).find(item=>item.id===lessonId);
      const previous=workspace.lessonPlans[lessonId]||{};
      workspace.lessonPlans[lessonId]={...previous,lessonId,cycleId:previous.cycleId||'cycle-connect-u01-u03',planType:'Plano Base Purple',status:lesson?.status||'RASCUNHO',theme:lesson?.theme||base.purpose,communicativeObjective:lesson?.communicativeObjective||'',duration:120,audience:'Connect 2026.2',version:previous.version||'v1.0-draft',revision:Number(previous.revision||1),baseVersion:false,curriculumId:'connect-2026-2',meetingNumber:lesson?.meetingNumber,meetingType:lesson?.meetingType,bookPages:lesson?.bookPages,unitRelations:lesson?.unitRelations||[],purpose:base.purpose,expectedOutcome:base.expectedOutcome,teacherPreparation:base.teacherPreparation,homework:base.homework||'',readyForNext:base.readyForNext||'',unitMastery:base.unitMastery||'',rapidSummary:base.rapidSummary,meetingArcs:base.meetingArcs||[],rapidCheck:{realLife:true,active:true,personalized:true,interactive:true,dynamic:true},stageAssignments:previous.stageAssignments||{presentation:'ready',practice:'ready',review:'ready',production:'ready',closing:'ready'},stages:base.stages,resources:batch.resources.filter(resource=>resource.meetingIds.includes(lessonId)).map(resource=>({...resource,url:'',link:''})),attachments:previous.attachments||[],variations:previous.variations||[],history:previous.history?.length?previous.history:[{id:`hist-${lessonId}-import`,at:'2026-09-04T12:00:00',actor:'Coordenação Pedagógica',action:'Importou lote Connect Units 01-03',detail:'Plano importado como rascunho/candidato a Plano Base Purple.'}],postClassFeedback:previous.postClassFeedback||[],aiSuggestions:previous.aiSuggestions||[]};
    }
    workspace.cycles=workspace.cycles||[];
    if(!workspace.cycles.some(item=>item.id==='cycle-connect-u01-u03'))workspace.cycles.unshift({id:'cycle-connect-u01-u03',title:'Connect 2026.2 • Units 01-03',courseId:'connect',unitId:'connect-u01',lessonIds:['connect-m02','connect-m03','connect-m04','connect-m05','connect-m06'],deadline:'2026-09-30T18:00:00',reviewer:'Coordenação Pedagógica',participantIds:['u-teach-ana','u-teach-eduardo'],status:'RASCUNHO',progress:20,contributionStatus:'on_track',scope:'Primeiro lote real Connect 2026.2',summary:'Meetings 02-06 importados como rascunho pedagógico/candidatos a Plano Base Purple.'});
    workspace.connectRealBatchVersion='connect-u01-u03-v1';
  }

