  function ensureWorkspace(){
    const db=getDb();
    if(!db.lessonPlansWorkspace||db.lessonPlansWorkspace.version<2)db.lessonPlansWorkspace=seedWorkspace();
    const workspace=db.lessonPlansWorkspace;
    workspace.version=4;
    workspace.ai=workspace.ai||{status:'unknown',lastError:'',updatedAt:''};
    workspace.collections=workspace.collections?.length?workspace.collections:[{id:'purple-way',name:'Purple Way',description:'Biblioteca pedagógica principal da Purple.',coverUrl:'',order:1,status:'active',bookIds:(workspace.courses||[]).map(course=>course.id)}];
    workspace.courses=workspace.courses||[];
    workspace.courses.forEach((course,index)=>{
      Object.assign(course,{collectionId:course.collectionId||'purple-way',description:course.description||`${course.name} reúne unidades, planos e recursos Purple.`,level:course.level||'',order:Number(course.order||index+1),status:course.status||'active',coverUrl:course.coverUrl||'',pdfUrl:course.pdfUrl||'',coverStoragePath:course.coverStoragePath||'',pdfStoragePath:course.pdfStoragePath||'',pedagogicalInfo:course.pedagogicalInfo||course.description||'',coverPositionX:Number(course.coverPositionX??50),coverPositionY:Number(course.coverPositionY??50),coverZoom:Number(course.coverZoom??100)});
      (course.units||[]).forEach(unit=>unit.content=unit.content||unit.theme||'');
    });
    for(const collection of workspace.collections){collection.bookIds=collection.bookIds?.length?collection.bookIds:workspace.courses.filter(course=>course.collectionId===collection.id).map(course=>course.id);collection.status=collection.status||'active';collection.order=Number(collection.order||1);}
    workspace.lessonPlans=workspace.lessonPlans||{};
    for(const course of workspace.courses)for(const unit of course.units||[])for(const lesson of unit.lessons||[])if(!workspace.lessonPlans[lesson.id])workspace.lessonPlans[lesson.id]=defaultPlan(lesson,unit,course);
    importConnectRealBatch(workspace);
    for(const plan of Object.values(workspace.lessonPlans)){
      plan.revision=Number(plan.revision||1);plan.baseVersion=Boolean(plan.baseVersion||plan.planType==='Plano Base Purple'||plan.status==='PUBLICADA');plan.postClassFeedback=plan.postClassFeedback||[];plan.aiSuggestions=plan.aiSuggestions||[];plan.attachments=plan.attachments||[];
      plan.resources=(plan.resources||[]).map(resource=>({id:resource.id||uid('res'),title:resource.title||resource.label||'Recurso',label:resource.label||resource.title||'Recurso',type:resource.type||'Link',description:resource.description||'',url:resource.url||resource.link||'',link:resource.link||resource.url||'',stageKey:resource.stageKey||'general'}));
      for(const stage of LESSON_STAGES){plan.stages[stage.key]=plan.stages[stage.key]||{};plan.stages[stage.key].studentBookPages=plan.stages[stage.key].studentBookPages||pagesFrom(plan.stages[stage.key].pages,'SB');plan.stages[stage.key].workbookPages=plan.stages[stage.key].workbookPages||pagesFrom(plan.stages[stage.key].pages,'WB');}
    }
    workspace.contributions=workspace.contributions||[];workspace.publishedFeed=workspace.publishedFeed||[];workspace.cycles=workspace.cycles||[];workspace.lastOpened=workspace.lastOpened||{courseId:'discover',unitId:'discover-u01',lessonId:'discover-u01-l01'};
    getState().lessonPlans=getState().lessonPlans||{view:'library',collectionId:'',courseId:'',unitId:'',lessonId:'',searchTerm:'',mode:'read',viewerPage:1,viewerZoom:100};
    return workspace;
  }

  function findCollection(id){const w=ensureWorkspace();return w.collections.find(item=>item.id===id)||w.collections[0]}
  function findCourse(id){const w=ensureWorkspace();return w.courses.find(item=>item.id===id)||w.courses[0]}
  function findUnit(courseId,unitId){const c=findCourse(courseId);return c?.units?.find(item=>item.id===unitId)||c?.units?.[0]}
  function findLessonMeta(lessonId){for(const course of ensureWorkspace().courses)for(const unit of course.units||[]){const lesson=(unit.lessons||[]).find(item=>item.id===lessonId);if(lesson)return {course,unit,lesson};}return {course:null,unit:null,lesson:null}}
  function findPlan(id){return ensureWorkspace().lessonPlans[id]||null}
  function findCycle(id){return ensureWorkspace().cycles.find(item=>item.id===id)||null}
  function collectionBooks(collection){const ids=new Set(collection.bookIds||[]);return ensureWorkspace().courses.filter(course=>course.collectionId===collection.id||ids.has(course.id)).sort((a,b)=>a.order-b.order)}
  function lessonCounts(unit){return (unit.lessons||[]).reduce((acc,lesson)=>{acc.total++;if(lesson.status==='PUBLICADA')acc.ready++;return acc},{total:0,ready:0})}
  function workflowLabel(status){return WORKFLOW_LABELS[status]||status||'Em preparação'}
  function statusClass(status){return String(status||'').toLowerCase().replace(/[^a-z0-9]+/g,'-')}
  function userLabel(id){return (getDb().users||[]).find(item=>item.id===id)?.name?.split(' — ')[0]||'Equipe Purple'}
  function totalStageMinutes(plan){return LESSON_STAGES.reduce((sum,stage)=>sum+Number(plan?.stages?.[stage.key]?.duration||0),0)}
  function saveHistory(plan,action,detail){plan.history=plan.history||[];plan.history.unshift({id:uid('hist-lp'),at:new Date().toISOString(),actor:userLabel(getUser()?.id),action,detail})}
  function bumpPlan(plan){plan.revision=Number(plan.revision||1)+1;const meta=findLessonMeta(plan.lessonId);if(meta.lesson){meta.lesson.status=plan.status;meta.lesson.version=plan.version}}
  async function savePlan(){return persist()}
  function setView(next){getState().lessonPlans={...(getState().lessonPlans||{}),mode:'read',...next};window.App?.renderPage?.()}
  function goModule(page='lesson-plans'){if(getState().page!==page)window.App?.go?.(page)}
  function openLibrary(){setView({view:'library',collectionId:'',courseId:'',unitId:'',lessonId:''});goModule()}
  function openCollection(collectionId){setView({view:'collection',collectionId,courseId:'',unitId:'',lessonId:''});goModule()}
  function openCourse(courseId){const c=findCourse(courseId);setView({view:'book',collectionId:c.collectionId,courseId,unitId:'',lessonId:''});goModule()}
  function openUnit(courseId,unitId){const c=findCourse(courseId);setView({view:'unit',collectionId:c.collectionId,courseId,unitId,lessonId:''});goModule()}
  function openLesson(lessonId){const m=findLessonMeta(lessonId);if(!m.lesson)return toast('Aula não encontrada.');ensureWorkspace().lastOpened={courseId:m.course.id,unitId:m.unit.id,lessonId};setView({view:'lesson',collectionId:m.course.collectionId,courseId:m.course.id,unitId:m.unit.id,lessonId,mode:'read'});goModule()}
  function canManagePlanning(){return can('lesson_plans.review')||can('lesson_plans.publish')||can('lesson_plans.cycles.manage')}
  function openManagement(){if(!canManagePlanning())return openLibrary();setView({view:'management'});goModule()}
  async function openBookViewer(courseId,page=1){const c=findCourse(courseId);if(c.pdfStoragePath){try{const url=await signedStorageUrl(c.pdfStoragePath);if(url)c.pdfUrl=url}catch(error){console.error('Lesson Plans — erro ao assinar PDF:',error);toast(`Não foi possível abrir o PDF seguro: ${error.message||error}`)}}setView({view:'viewer',collectionId:c.collectionId,courseId,viewerPage:pageFrom(page),viewerZoom:100});goModule()}
  function openStageInBook(lessonId,stageKey){const m=findLessonMeta(lessonId);const s=findPlan(lessonId)?.stages?.[stageKey]||{};openBookViewer(m.course.id,s.studentBookPages||s.pages||1)}
  function setEditMode(lessonId){const m=findLessonMeta(lessonId);setView({view:'lesson',collectionId:m.course.collectionId,courseId:m.course.id,unitId:m.unit.id,lessonId,mode:'edit'})}

  function renderCover(item,kind='book'){return item.coverUrl?`<div class="lp-cover ${kind}"${coverStyle(item)}></div>`:`<div class="lp-cover ${kind} placeholder"><span>${escape(item.name?.slice(0,2).toUpperCase()||'PW')}</span><small>Capa real não cadastrada</small></div>`}
  function renderCrumbs(items){return `<div class="lp-crumbs"><button onclick="PurpleLessonPlans.openLibrary()">Coleções</button>${items.map(item=>`<span>›</span><button onclick="${item.action}">${escape(item.label)}</button>`).join('')}</div>`}
  function renderLessonNav(active='library'){const manage=canManagePlanning();const items=[['library','Biblioteca','PurpleLessonPlans.openLibrary()'],['plans','Planejamentos',manage?'PurpleLessonPlans.openManagement()':'PurpleLessonPlans.openLibrary()'],['contributions','Minhas contribuições',"window.App.go('lesson-contributions')"]];if(manage)items.push(['management','Gestão','PurpleLessonPlans.openManagement()']);return `<nav class="lp-subnav">${items.map(([id,label,action])=>`<button class="${active===id?'active':''}" onclick="${action}">${escape(label)}</button>`).join('')}</nav>`}
  function libraryStatusLabel(status){return {active:'Ativa',draft:'Em preparo',archived:'Arquivada'}[status]||status||'Em preparo'}

  function renderTeacherHome(){
    const w=ensureWorkspace(),last=w.lastOpened||{},m=findLessonMeta(last.lessonId||'discover-u01-l01'),mine=w.contributions.filter(item=>item.assigneeId===getUser()?.id&&['on_track','due_today','overdue'].includes(item.status)),books=collectionBooks(findCollection('purple-way')).slice(0,5);
    return `<div class="page lesson-home-page lp-library-shell"><section class="lp-teacher-hero"><div><span class="eyebrow">Biblioteca Pedagógica Purple</span><h1>${escape(typeof window.greeting==='function'?window.greeting():'Olá!')}</h1><p>Encontre a aula, consulte o livro, use os recursos e contribua para melhorar como a Purple ensina.</p></div><button class="btn primary" onclick="PurpleLessonPlans.openLibrary()">Abrir Biblioteca</button></section><section class="lp-home-continue"><div><span class="eyebrow">Continuar de onde parei</span><h2>${escape(m.course?.name||'Discover')} • ${escape(m.unit?.title||'Unit 01')} • ${escape(m.lesson?.title||'Lesson 01')}</h2><p>${escape(m.lesson?.theme||'Meet the group')}</p></div><button class="btn primary" onclick="PurpleLessonPlans.openLesson('${escape(last.lessonId||'discover-u01-l01')}')">Continuar aula</button></section><div class="lp-home-grid"><section class="panel"><div class="panel-head"><div><span class="eyebrow">Minha biblioteca</span><h3>Purple Way</h3></div></div><div class="lp-mini-book-row">${books.map(book=>`<button onclick="PurpleLessonPlans.openCourse('${escape(book.id)}')">${renderCover(book,'mini')}<b>${escape(book.name)}</b></button>`).join('')}</div></section><section class="panel"><div class="panel-head"><div><span class="eyebrow">Precisa da sua contribuição</span><h3>${fmtNumber(mine.length)} item(ns)</h3></div></div>${mine.slice(0,2).map(item=>{const meta=findLessonMeta(item.lessonId);return `<article class="lp-compact-action"><b>${escape(meta.course?.name)} • ${escape(meta.unit?.title)}</b><span>${escape(meta.lesson?.title)} • ${escape(item.stageKey)}</span><button class="btn ghost small" onclick="PurpleLessonPlans.openLesson('${escape(item.lessonId)}')">Contribuir</button></article>`}).join('')||'<p class="muted">Nada urgente agora. Biblioteca liberada para preparar aula.</p>'}</section></div><section class="panel"><div class="panel-head"><div><span class="eyebrow">Novos planos publicados</span><h3>Atualizações da Biblioteca</h3></div></div><div class="lp-published-row">${w.publishedFeed.slice(0,3).map(item=>{const meta=findLessonMeta(item.lessonId);return `<button onclick="PurpleLessonPlans.openLesson('${escape(item.lessonId)}')"><b>${escape(meta.course?.name)} • ${escape(meta.unit?.title)}</b><span>${escape(meta.lesson?.title)} publicado em ${fmtDate(item.publishedAt)}</span></button>`}).join('')||'<p class="muted">Nenhuma publicação recente.</p>'}</div></section></div>`;
  }

  function renderLibrary(){
    const w=ensureWorkspace(),state=getState().lessonPlans||{},term=String(state.searchTerm||'').trim().toLowerCase();
    return `<div class="page lesson-page lp-library-shell">${renderLessonNav('library')}<section class="lp-library-hero"><div><span class="eyebrow">Biblioteca pedagógica digital</span><h1>Como a Purple ensina.</h1><p>Explore por coleção, livro, unidade e aula. A colaboração existe para melhorar essa biblioteca, não para roubar a cena.</p></div><div class="lp-search-box"><label>Qual aula você vai ensinar?</label><input id="lpLibrarySearch" value="${escape(state.searchTerm||'')}" oninput="PurpleLessonPlans.updateSearch(this.value)" placeholder="Discover, Unit 1, simple past, food, introductions, speaking..."/></div></section>${term?renderSearchResults(term):`<section><div class="section-title"><div><span class="eyebrow">Coleções</span><h2>Programas Purple</h2></div></div><div class="lp-collection-grid">${w.collections.sort((a,b)=>a.order-b.order).map(collection=>`<button class="lp-collection-card" onclick="PurpleLessonPlans.openCollection('${escape(collection.id)}')">${renderCover(collection,'collection')}<span>${escape(libraryStatusLabel(collection.status))}</span><h3>${escape(collection.name)}</h3><p>${escape(collection.description)}</p><small>${fmtNumber(collectionBooks(collection).length)} livros/programas</small></button>`).join('')}</div></section>`}</div>`;
  }

  function renderSearchResults(term){
    const results=[],matches=value=>String(value||'').toLowerCase().includes(term);
    for(const course of ensureWorkspace().courses){if(matches([course.name,course.description,course.level].join(' ')))results.push(['Livro',course.name,course.description,`PurpleLessonPlans.openCourse('${escape(course.id)}')`]);for(const unit of course.units||[]){if(matches([unit.title,unit.theme,unit.objective,unit.content,(unit.vocabulary||[]).join(' '),(unit.grammar||[]).join(' '),(unit.skills||[]).join(' ')].join(' ')))results.push(['Unidade',`${course.name} • ${unit.title}`,unit.theme,`PurpleLessonPlans.openUnit('${escape(course.id)}','${escape(unit.id)}')`]);for(const lesson of unit.lessons||[]){const plan=findPlan(lesson.id);if(matches([lesson.title,lesson.theme,lesson.communicativeObjective,plan?.communicativeObjective,Object.values(plan?.stages||{}).map(stage=>[stage.objective,stage.activity,stage.instructions,stage.pages].join(' ')).join(' ')].join(' ')))results.push(['Aula',`${course.name} • ${unit.title} • ${lesson.title}`,lesson.theme,`PurpleLessonPlans.openLesson('${escape(lesson.id)}')`]);}}}
    return `<section class="panel lp-search-results"><div class="panel-head"><div><span class="eyebrow">Resultados</span><h3>${fmtNumber(results.length)} resultado(s) para “${escape(term)}”</h3></div></div><div class="lp-result-list">${results.map(([kind,title,subtitle,action])=>`<button onclick="${action}"><span>${escape(kind)}</span><b>${escape(title)}</b><small>${escape(subtitle)}</small></button>`).join('')||'<p class="muted">Nenhum conteúdo encontrado.</p>'}</div></section>`;
  }

  function renderCollection(){
    const collection=findCollection(getState().lessonPlans?.collectionId),books=collectionBooks(collection);
    return `<div class="page lesson-page lp-library-shell">${renderLessonNav('library')}${renderCrumbs([{label:collection.name,action:`PurpleLessonPlans.openCollection('${escape(collection.id)}')`}])}<section class="lp-collection-head">${renderCover(collection,'collection-large')}<div><span class="eyebrow">Coleção</span><h1>${escape(collection.name)}</h1><p>${escape(collection.description)}</p></div></section><div class="lp-book-grid">${books.map(book=>`<button class="lp-book-card" onclick="PurpleLessonPlans.openCourse('${escape(book.id)}')">${renderCover(book,'book')}<div><span>${escape(book.level||'')}</span><h3>${escape(book.name)}</h3><p>${escape(book.description)}</p><small>${fmtNumber((book.units||[]).length)} unidades • ${escape(libraryStatusLabel(book.status))}</small></div></button>`).join('')}</div></div>`;
  }

  function renderBook(){
    const course=findCourse(getState().lessonPlans?.courseId),collection=findCollection(course.collectionId),units=course.units||[],totalLessons=units.reduce((s,u)=>s+(u.lessons||[]).length,0);
    return `<div class="page lesson-page lp-library-shell">${renderLessonNav('library')}${renderCrumbs([{label:collection.name,action:`PurpleLessonPlans.openCollection('${escape(collection.id)}')`},{label:course.name,action:`PurpleLessonPlans.openCourse('${escape(course.id)}')`}])}<section class="lp-book-head">${renderCover(course,'book-large')}<div><span class="eyebrow">Livro</span><h1>${escape(course.name)}</h1><p>${escape(course.description)}</p><div class="lp-meta-row"><span>${escape(course.level||'Nível não cadastrado')}</span><span>${fmtNumber(units.length)} unidades</span><span>${fmtNumber(totalLessons)} aulas</span></div><p><b>Cobertura pedagógica:</b> ${escape(course.pedagogicalInfo||'Em cadastramento.')}</p><div class="section-actions" style="justify-content:flex-start"><button class="btn primary" onclick="PurpleLessonPlans.openBookViewer('${escape(course.id)}',1)">Abrir livro</button>${can('lesson_plans.cycles.manage')?`<button class="btn ghost" onclick="PurpleLessonPlans.openBookEditor('${escape(course.id)}')">Gerenciar livro</button>`:''}</div></div></section><section><div class="section-title"><div><span class="eyebrow">Unidades</span><h2>${escape(course.name)}</h2></div></div><div class="lp-unit-grid">${units.map(unit=>{const counts=lessonCounts(unit),resources=(unit.lessons||[]).reduce((s,l)=>s+(findPlan(l.id)?.resources||[]).length,0);return `<button class="lp-unit-card" onclick="PurpleLessonPlans.openUnit('${escape(course.id)}','${escape(unit.id)}')"><span>${escape(unit.title)}</span><h3>${escape(unit.theme)}</h3><p>${escape(unit.objective)}</p><div><b>${counts.ready?`${counts.ready} plano(s) disponível(is)`:'Em preparação'}</b><small>${fmtNumber(resources)} recursos</small></div></button>`}).join('')||'<div class="empty"><h3>Unidades em preparação</h3><p>Este livro já está pronto para receber conteúdo pedagógico.</p></div>'}</div></section></div>`;
  }

  function renderUnit(){
    const s=getState().lessonPlans||{},course=findCourse(s.courseId),unit=findUnit(course.id,s.unitId),first=(unit.lessons||[])[0];
    return `<div class="page lesson-page lp-library-shell">${renderLessonNav('library')}${renderCrumbs([{label:findCollection(course.collectionId).name,action:`PurpleLessonPlans.openCollection('${escape(course.collectionId)}')`},{label:course.name,action:`PurpleLessonPlans.openCourse('${escape(course.id)}')`},{label:unit.title,action:`PurpleLessonPlans.openUnit('${escape(course.id)}','${escape(unit.id)}')`}])}<section class="lp-unit-hero"><div><span class="eyebrow">${escape(course.name)}</span><h1>${escape(unit.title)} — ${escape(unit.theme)}</h1><p>${escape(unit.objective)}</p></div><div class="section-actions">${can('lesson_plans.cycles.manage')?`<button class="btn ghost" onclick="PurpleLessonPlans.openUnitMapEditor('${escape(course.id)}','${escape(unit.id)}')">Editar mapa</button>`:''}${first?`<button class="btn primary" onclick="PurpleLessonPlans.openLesson('${escape(first.id)}')">Abrir Lesson Plan</button>`:''}</div></section>${renderUnitSummary(unit,course)}<section><div class="section-title"><div><span class="eyebrow">Lesson Plans</span><h2>Aulas da unidade</h2></div></div><div class="lp-lesson-list">${(unit.lessons||[]).map(lesson=>{const plan=findPlan(lesson.id);return `<button class="lp-lesson-card" onclick="PurpleLessonPlans.openLesson('${escape(lesson.id)}')"><span>${escape(lesson.title)}</span><h3>${escape(lesson.theme)}</h3><p>${escape(lesson.communicativeObjective)}</p><div><b>${escape(workflowLabel(plan?.status||lesson.status))}</b><small>${fmtNumber((plan?.resources||[]).length)} recursos</small></div></button>`}).join('')}</div></section></div>`;
  }

  function renderUnitSummary(unit,course){
    const entries=[['Objetivos',unit.objective],['Conteúdo',unit.content||unit.theme],['Vocabulary',(unit.vocabulary||[]).join(' • ')],['Grammar / Language',(unit.grammar||[]).join(' • ')],['Communicative Functions',(unit.communicativeFunctions||[]).join(' • ')],['Expected Outcomes',unit.expectedOutcome],['Skills',(unit.skills||[]).join(' • ')],['Páginas do livro',`Student Book ${unit.studentBookPages||'—'} • Workbook ${unit.workbookPages||'—'}`]];
    return `<section class="panel lp-editorial-summary"><div class="panel-head"><div><span class="eyebrow">Resumo pedagógico da unidade</span><h3>${escape(course.name)} • ${escape(unit.title)}</h3></div><button class="btn soft small" onclick="PurpleLessonPlans.openBookViewer('${escape(course.id)}','${escape(unit.studentBookPages||1)}')">Abrir páginas</button></div><div class="lp-summary-grid">${entries.map(([label,value])=>`<div><span>${escape(label)}</span><p>${escape(value||'—')}</p></div>`).join('')}</div></section>`;
  }

  function renderLesson(){
    const s=getState().lessonPlans||{},m=findLessonMeta(s.lessonId),plan=findPlan(s.lessonId);if(!m.lesson||!plan)return `<div class="page"><div class="empty"><h3>Planejamento não encontrado</h3><p>Selecione uma aula da biblioteca.</p></div></div>`;
    const edit=s.mode==='edit'&&can('lesson_plans.edit'),cycle=findCycle(plan.cycleId);
    return `<div class="page lesson-page lp-library-shell">${renderLessonNav('library')}${renderCrumbs([{label:findCollection(m.course.collectionId).name,action:`PurpleLessonPlans.openCollection('${escape(m.course.collectionId)}')`},{label:m.course.name,action:`PurpleLessonPlans.openCourse('${escape(m.course.id)}')`},{label:m.unit.title,action:`PurpleLessonPlans.openUnit('${escape(m.course.id)}','${escape(m.unit.id)}')`},{label:m.lesson.title,action:`PurpleLessonPlans.openLesson('${escape(plan.lessonId)}')`}])}<section class="lp-lesson-hero"><div><span class="eyebrow">${escape(plan.curriculumId||m.course.name)} • ${escape(m.unit.title)}</span><h1>${escape(m.lesson.title)} — ${escape(plan.theme)}</h1><p>${escape(plan.communicativeObjective)}</p><div class="lp-meta-row"><span>${plan.meetingNumber?`Meeting ${fmtNumber(plan.meetingNumber)}`:'Plano Base Purple'}</span><span>${escape(plan.meetingType==='transition'?'Transition Meeting':'Método R.A.P.I.D.')}</span><span>${fmtNumber(plan.duration)} min + 10 break</span><span>Rev. ${fmtNumber(plan.revision)}</span></div></div><div class="section-actions">${!edit&&can('lesson_plans.edit')?`<button class="btn ghost" onclick="PurpleLessonPlans.setEditMode('${escape(plan.lessonId)}')">Editar plano</button>`:''}${edit?`<button class="btn primary" onclick="PurpleLessonPlans.saveLessonEditor('${escape(plan.lessonId)}')">Salvar</button><button class="btn ghost" onclick="PurpleLessonPlans.openLesson('${escape(plan.lessonId)}')">Cancelar</button>`:''}<button class="btn soft" onclick="PurpleLessonPlans.printPlan('${escape(plan.lessonId)}')">Imprimir</button><button class="btn soft" onclick="PurpleLessonPlans.generatePlanPdf('${escape(plan.lessonId)}')">Gerar PDF</button></div></section><section class="lp-lesson-layout"><main>${renderMeetingOverview(plan,m)}${renderTeacherQuickView(plan)}${renderRapidCompact(plan)}${renderLearningArcs(plan)}${renderLessonFlow(plan,edit)}${renderResources(plan,edit)}${renderCollectiveContribution(plan,cycle)}${renderHistory(plan)}</main><aside>${renderBookContext(m.course,m.unit,plan)}${renderAiPanel(plan)}${renderFeedback(plan)}</aside></section></div>`;
  }

  function renderMeetingOverview(plan,m){const relations=(plan.unitRelations||[]).map(rel=>{const unit=(m.course?.units||[]).find(item=>item.id===rel.unitId);return `${unit?.title||rel.unitId} ${unit?.theme?`— ${unit.theme}`:''} • pp.${rel.pages}`}).join(' | ');return `<section class="panel lp-meeting-overview"><div class="panel-head"><div><span class="eyebrow">Currículo operacional</span><h3>${escape(plan.meetingNumber?`Class Meeting ${plan.meetingNumber}`:'Lesson Plan')}</h3></div><b>${escape(plan.bookPages||m.lesson.bookPages||'')}</b></div><div class="lp-summary-grid"><div><span>Unit(s)</span><p>${escape(relations||m.unit.title)}</p></div><div><span>Objetivo</span><p>${escape(plan.communicativeObjective)}</p></div><div><span>Teacher Preparation</span><p>${escape(plan.teacherPreparation||'—')}</p></div><div><span>Expected Outcome</span><p>${escape(plan.expectedOutcome||'—')}</p></div><div><span>Ready / Mastery</span><p>${escape(plan.readyForNext||plan.unitMastery||'—')}</p></div><div><span>R.A.P.I.D.</span><p>${escape(plan.rapidSummary||'—')}</p></div></div></section>`}
  function renderTeacherQuickView(plan){const current=LESSON_STAGES.map(stage=>({stage,data:plan.stages?.[stage.key]||{}})).find(item=>item.data.duration)||{stage:LESSON_STAGES[0],data:{}};return `<section class="panel lp-teacher-quick"><div><span class="eyebrow">Teacher Quick View</span><h3>${escape(current.stage.label)} • ${fmtNumber(current.data.duration||0)} min</h3><p>${escape(current.data.instructions||current.data.activity||'Abra o Lesson Flow para conduzir a aula.')}</p></div><div><b>Páginas</b><span>${escape(current.data.studentBookPages||current.data.pages||plan.bookPages||'—')}</span></div><div><b>Interação</b><span>${escape(current.data.interaction||'—')}</span></div><div><b>Próximo passo</b><span>${escape(current.data.successCriteria||plan.readyForNext||'Monitorar evidência comunicativa.')}</span></div></section>`}
  function renderLearningArcs(plan){if(!plan.meetingArcs?.length)return '';return `<section class="panel lp-learning-arcs"><div class="panel-head"><div><span class="eyebrow">Transition Learning Arcs</span><h3>Meeting 05: Unit 02 -> Unit 03</h3></div></div>${plan.meetingArcs.map(arc=>`<article><div><h4>${escape(arc.title)}</h4><span>${fmtNumber(arc.duration)} min • pp.${escape(arc.pages)}</span></div><p>${escape(arc.objective)}</p><ol>${(arc.steps||[]).map(step=>`<li>${escape(step)}</li>`).join('')}</ol></article>`).join('')}</section>`}
  function renderRapidCompact(plan){return `<section class="panel lp-rapid-compact"><div><span class="eyebrow">R.A.P.I.D. Check</span><h3>Metodologia orientando a aula</h3></div><div>${RAPID_PRINCIPLES.map(item=>`<span class="${plan.rapidCheck?.[item.key]?'active':''}"><b>${item.short}</b>${escape(item.label)}</span>`).join('')}</div></section>`}
  function renderLessonFlow(plan,edit){return `<section class="panel lp-flow"><div class="panel-head"><div><span class="eyebrow">Lesson Flow</span><h3>Guia pedagógico digital</h3></div></div>${LESSON_STAGES.map((stage,index)=>renderFlowStage(plan,stage,index+1,edit)).join('')}</section>`}
  function renderFlowStage(plan,stage,index,edit){const data=plan.stages[stage.key]||{};if(edit)return `<article class="lp-flow-stage edit"><h3>${String(index).padStart(2,'0')} ${escape(stage.label)}</h3><div class="form-grid cols-2"><div class="field"><label>Objetivo</label><textarea id="lpEdit-${stage.key}-objective">${escape(data.objective||'')}</textarea></div><div class="field"><label>Atividade</label><textarea id="lpEdit-${stage.key}-activity">${escape(data.activity||'')}</textarea></div><div class="field"><label>Orientação</label><textarea id="lpEdit-${stage.key}-instructions">${escape(data.instructions||'')}</textarea></div><div class="field"><label>Teacher notes</label><textarea id="lpEdit-${stage.key}-observations">${escape(data.observations||'')}</textarea></div></div><div class="form-grid cols-4"><div class="field"><label>Tempo</label><input id="lpEdit-${stage.key}-duration" type="number" value="${escape(data.duration||0)}"/></div><div class="field"><label>Interação</label><input id="lpEdit-${stage.key}-interaction" value="${escape(data.interaction||'')}"/></div><div class="field"><label>Student Book</label><input id="lpEdit-${stage.key}-studentBookPages" value="${escape(data.studentBookPages||'')}"/></div><div class="field"><label>Workbook</label><input id="lpEdit-${stage.key}-workbookPages" value="${escape(data.workbookPages||'')}"/></div></div></article>`;return `<article class="lp-flow-stage"><div class="lp-stage-number">${String(index).padStart(2,'0')}</div><div><div class="lp-stage-title"><h3>${escape(stage.label)}</h3><span>${fmtNumber(data.duration||0)} min</span></div><dl><dt>Objetivo</dt><dd>${escape(data.objective||'—')}</dd><dt>Orientação</dt><dd>${escape(data.instructions||'—')}</dd><dt>Atividade</dt><dd>${escape(data.activity||'—')}</dd><dt>Interação</dt><dd>${escape(data.interaction||'—')}</dd><dt>Páginas</dt><dd>Student Book ${escape(data.studentBookPages||pagesFrom(data.pages,'SB')||'—')} • Workbook ${escape(data.workbookPages||pagesFrom(data.pages,'WB')||'—')} ${(data.studentBookPages||data.pages)?`<button class="link-button" onclick="PurpleLessonPlans.openStageInBook('${escape(plan.lessonId)}','${escape(stage.key)}')">Abrir no livro</button>`:''}</dd><dt>Recursos</dt><dd>${escape((data.resources||[]).join(' • ')||'—')}</dd><dt>Teacher notes</dt><dd>${escape(data.observations||'—')}</dd></dl></div></article>`}
  function renderResources(plan){return `<section class="panel lp-resources"><div class="panel-head"><div><span class="eyebrow">Recursos da aula</span><h3>Materiais, jogos, vídeos e links</h3></div>${can('lesson_plans.edit')?`<button class="btn primary small" onclick="PurpleLessonPlans.openResourceEditor('${escape(plan.lessonId)}')">+ Adicionar recurso</button>`:''}</div><div class="lp-resource-grid">${(plan.resources||[]).map(renderResourceCard).join('')||'<p class="muted">Nenhum recurso cadastrado.</p>'}</div></section>`}
  function renderResourceCard(resource){const yt=youtubeId(resource.url);return `<article class="lp-resource-card"><div class="lp-resource-icon">${iconForType(resource.type)}</div><div><span>${escape(resource.type)}${resource.stageKey&&resource.stageKey!=='general'?` • ${escape(resource.stageKey)}`:''}</span><h4>${escape(resource.title||resource.label)}</h4><p>${escape(resource.description||'')}</p>${yt?`<img alt="" src="https://img.youtube.com/vi/${escape(yt)}/hqdefault.jpg" loading="lazy"/>`:''}<button class="btn soft small lp-resource-action" onclick="PurpleLessonPlans.openResource('${escape(resource.id)}')">${escape(resourceActionLabel(resource.type))}</button></div></article>`}
  function renderCollectiveContribution(plan,cycle){const rows=ensureWorkspace().contributions.filter(item=>item.lessonId===plan.lessonId);return `<section class="panel lp-collective"><div><span class="eyebrow">Contribuição coletiva</span><h3>${fmtNumber(new Set(rows.map(item=>item.assigneeId)).size)} colaboradores</h3><p>Última atualização ${fmtDateTime(rows[0]?.updatedAt||plan.history?.[0]?.at||'')}</p></div><div class="section-actions"><button class="btn ghost small" onclick="window.App.go('lesson-contributions')">Contribuir</button><button class="btn soft small" onclick="PurpleLessonPlans.openHistory('${escape(plan.lessonId)}')">Ver histórico</button>${can('lesson_plans.cycles.manage')?`<button class="btn ghost small" onclick="PurpleLessonPlans.openCycleEditor('${escape(cycle?.id||'')}')">Gerenciar ciclo</button>`:''}</div></section>`}
  function renderHistory(plan){return `<section class="panel lp-history"><div class="panel-head"><div><span class="eyebrow">Histórico</span><h3>Versionamento e evolução</h3></div></div><div class="timeline">${(plan.history||[]).slice(0,5).map(item=>`<div class="timeline-item"><b>${escape(item.action)}</b><p>${escape(item.detail)}</p><time>${fmtDateTime(item.at)} • ${escape(item.actor)}</time></div>`).join('')}</div></section>`}
  function renderBookContext(course,unit){return `<section class="panel lp-book-side">${renderCover(course,'mini')}<div><span class="eyebrow">Livro digital</span><h3>${escape(course.name)}</h3><p>${course.pdfUrl||course.pdfStoragePath?'PDF associado ao cadastro.':'PDF real ainda não cadastrado. Viewer disponível quando a coordenação associar arquivo seguro.'}</p><button class="btn primary small" onclick="PurpleLessonPlans.openBookViewer('${escape(course.id)}','${escape(unit.studentBookPages||1)}')">Abrir livro</button></div></section>`}
  function renderAiPanel(plan){return `<section class="panel lesson-side-panel"><div class="panel-head"><div><span class="eyebrow">Assistente Purple</span><h3>Ações contextuais</h3></div></div>${(ensureWorkspace().ai.status==='unavailable'||!can('lesson_plans.ai'))?`<div class="alert yellow"><div class="alert-icon">!</div><div><b>Assistente Purple ainda não configurado.</b><span>O restante continua funcional.</span></div></div>`:''}<div class="lesson-ai-actions"><button class="btn ghost small" onclick="PurpleLessonPlans.runAiAction('${escape(plan.lessonId)}','rapid_gap','')">Como deixar mais R.A.P.I.D.?</button><button class="btn soft small" onclick="PurpleLessonPlans.runAiAction('${escape(plan.lessonId)}','extra_activity','')">Criar atividade extra</button></div><div class="lesson-ai-suggestions">${(plan.aiSuggestions||[]).map(item=>`<article class="lesson-ai-card"><h4>${escape(item.title||'Sugestão')}</h4><p>${escape(item.preview||'')}</p></article>`).join('')||'<p class="muted">Nenhuma sugestão ainda.</p>'}</div></section>`}
  function renderFeedback(plan){return `<section class="panel lesson-side-panel"><div class="panel-head"><div><span class="eyebrow">Feedback pós-aula</span><h3>Melhoria contínua</h3></div><button class="btn ghost small" onclick="PurpleLessonPlans.openFeedbackModal('${escape(plan.lessonId)}')">Registrar</button></div><div class="lesson-resource-stack">${(plan.postClassFeedback||[]).map(item=>`<article><b>${escape(item.actor)}</b><p>${escape(item.note)}</p><small>${fmtDateTime(item.at)}</small></article>`).join('')||'<p class="muted">Nenhum feedback pós-aula registrado.</p>'}</div></section>`}

  function renderViewer(){const s=getState().lessonPlans||{},course=findCourse(s.courseId),page=Number(s.viewerPage||1),zoom=Number(s.viewerZoom||100);return `<div class="page lesson-page lp-library-shell">${renderLessonNav('library')}${renderCrumbs([{label:findCollection(course.collectionId).name,action:`PurpleLessonPlans.openCollection('${escape(course.collectionId)}')`},{label:course.name,action:`PurpleLessonPlans.openCourse('${escape(course.id)}')`},{label:'Livro Digital',action:`PurpleLessonPlans.openBookViewer('${escape(course.id)}',${page})`}])}<section class="lp-viewer-shell"><div class="lp-viewer-toolbar"><button class="btn ghost small" onclick="PurpleLessonPlans.viewerPrev()">Página anterior</button><span>Página <input id="lpViewerPage" value="${page}" onchange="PurpleLessonPlans.viewerGo(this.value)"/></span><button class="btn ghost small" onclick="PurpleLessonPlans.viewerNext()">Próxima página</button><button class="btn soft small" onclick="PurpleLessonPlans.viewerZoom(-10)">-</button><span>${zoom}%</span><button class="btn soft small" onclick="PurpleLessonPlans.viewerZoom(10)">+</button><button class="btn soft small" onclick="PurpleLessonPlans.viewerFit('width')">Ajustar largura</button><button class="btn soft small" onclick="PurpleLessonPlans.viewerFullscreen()">Tela cheia</button></div><div class="lp-viewer-body">${course.pdfUrl?`<iframe title="Livro ${escape(course.name)}" src="${escape(course.pdfUrl)}#page=${page}&zoom=${zoom}"></iframe>`:`<div class="lp-viewer-placeholder"><h2>${escape(course.name)}</h2><p>${course.pdfStoragePath?'O arquivo está associado, mas não foi possível gerar o link seguro nesta sessão. Tente abrir novamente após autenticar.':'PDF real ainda não associado. Coordenação/Direção pode cadastrar uma URL segura do livro em “Gerenciar livro”.'}</p><p>Não há download destacado na experiência normal; o objetivo é consulta integrada.</p>${can('lesson_plans.cycles.manage')?`<button class="btn primary" onclick="PurpleLessonPlans.openBookEditor('${escape(course.id)}')">Associar PDF/capa</button>`:''}</div>`}</div></section></div>`}

  function renderBookAssetManager(){
    const books=ensureWorkspace().courses.slice().sort((a,b)=>a.order-b.order);
    return `<section class="panel lp-asset-manager"><div class="panel-head"><div><span class="eyebrow">Capas e livros digitais</span><h3>Biblioteca visual da Purple</h3><small>Cadastre capas reais e PDFs por link seguro/storage. Nada é armazenado de forma improvisada no navegador.</small></div></div><div class="lp-asset-grid">${books.map(book=>`<article class="lp-asset-card">${renderCover(book,'asset')}<div><span>${escape(findCollection(book.collectionId)?.name||'Coleção')}</span><h4>${escape(book.name)}</h4><p>${escape(book.level||'Nível não cadastrado')}</p><div class="lp-asset-status"><b class="${book.coverUrl||book.coverStoragePath?'ok':'wait'}">${book.coverUrl||book.coverStoragePath?'Capa cadastrada':'Sem capa real'}</b><b class="${book.pdfUrl||book.pdfStoragePath?'ok':'wait'}">${book.pdfUrl||book.pdfStoragePath?'PDF cadastrado':'Sem PDF'}</b></div><div class="section-actions" style="justify-content:flex-start"><button class="btn primary small" onclick="PurpleLessonPlans.openBookEditor('${escape(book.id)}')">Alterar capa/PDF</button><button class="btn ghost small" onclick="PurpleLessonPlans.openCourse('${escape(book.id)}')">Ver livro</button></div></div></article>`).join('')}</div></section>`;
  }
  function renderManagement(){const w=ensureWorkspace();return `<div class="page lesson-page lp-library-shell">${renderLessonNav('management')}<section class="lp-management-hero"><div><span class="eyebrow">Gestão de planejamentos</span><h1>Construção, revisão e publicação ficam aqui.</h1><p>Ciclos, contribuições abertas, R.A.P.I.D. checks, aprovações e histórico continuam como camada administrativa.</p></div>${can('lesson_plans.cycles.manage')?'<button class="btn primary" onclick="PurpleLessonPlans.openCycleEditor()">Criar ciclo</button>':''}</section>${renderBookAssetManager()}<section class="grid cols-4 lesson-kpi-grid"><div class="metric-card"><div class="label">Ciclos ativos</div><div class="value">${fmtNumber(w.cycles.length)}</div><div class="note">Fluxos em andamento</div></div><div class="metric-card"><div class="label">Planos publicados</div><div class="value">${fmtNumber(Object.values(w.lessonPlans).filter(plan=>plan.status==='PUBLICADA').length)}</div><div class="note">Biblioteca oficial</div></div><div class="metric-card"><div class="label">Contribuições abertas</div><div class="value">${fmtNumber(w.contributions.filter(item=>['on_track','due_today','overdue'].includes(item.status)).length)}</div><div class="note">Com responsável</div></div><div class="metric-card"><div class="label">R.A.P.I.D. completos</div><div class="value">${fmtNumber(Object.values(w.lessonPlans).filter(plan=>RAPID_PRINCIPLES.every(item=>plan.rapidCheck?.[item.key])).length)}</div><div class="note">Check metodológico</div></div></section><section class="dashboard-layout"><div class="panel"><div class="panel-head"><div><span class="eyebrow">Ciclo de planejamento</span><h3>Em andamento agora</h3></div></div><div class="lesson-cycle-list">${w.cycles.map(cycle=>`<article class="lesson-cycle-card"><div class="lesson-cycle-top"><div><b>${escape(cycle.title)}</b><p>${escape(cycle.scope)} • ${escape(workflowLabel(cycle.status))}</p></div><span class="status ${statusClass(cycle.status)}">${escape(DEADLINE_LABELS[cycle.contributionStatus]||DEADLINE_LABELS.on_track)}</span></div><div class="lesson-cycle-meta"><span>Prazo: ${fmtDate(cycle.deadline)}</span><span>Equipe: ${(cycle.participantIds||[]).map(userLabel).join(', ')}</span><span>Revisor: ${escape(cycle.reviewer)}</span></div><div class="progress"><span style="width:${Math.max(8,cycle.progress||0)}%"></span></div><small>${escape(cycle.summary)}</small><div class="section-actions" style="justify-content:flex-start;margin-top:12px"><button class="btn primary small" onclick="PurpleLessonPlans.openLesson('${escape(cycle.lessonIds[0])}')">Abrir conteúdo</button>${can('lesson_plans.cycles.manage')?`<button class="btn ghost small" onclick="PurpleLessonPlans.openCycleEditor('${escape(cycle.id)}')">Editar ciclo</button>`:''}</div></article>`).join('')}</div></div><div class="panel"><div class="panel-head"><div><span class="eyebrow">Publicados</span><h3>Planos base recentes</h3></div></div><div class="lesson-brief-list">${w.publishedFeed.slice(0,5).map(item=>{const meta=findLessonMeta(item.lessonId);return `<article class="lesson-brief-item compact"><div><b>${escape(meta.course?.name||'Curso')} • ${escape(meta.unit?.title||'Unit')}</b><p>${escape(meta.lesson?.title||'Lesson')}</p><small>Publicado em ${fmtDate(item.publishedAt)}</small></div><button class="btn ghost small" onclick="PurpleLessonPlans.openLesson('${escape(item.lessonId)}')">Ver plano</button></article>`}).join('')}</div></div></section></div>`}

  function contributionRows(){const teacherMode=getUser()?.role==='teacher';return ensureWorkspace().contributions.filter(item=>!teacherMode||item.assigneeId===getUser()?.id).map(item=>{const meta=findLessonMeta(item.lessonId),cycle=findCycle(item.cycleId);return {...item,meta,cycle,stageLabel:LESSON_STAGES.find(stage=>stage.key===item.stageKey)?.label||item.stageKey}})}
  function renderContributions(){const rows=contributionRows();return `<div class="page lesson-page lp-library-shell">${renderLessonNav('contributions')}<div class="section-title"><div><span class="eyebrow">Minhas contribuições</span><h2>Melhorias pontuais na Biblioteca</h2><p>As contribuições existem para refinar aulas Purple já estruturadas.</p></div></div><section class="panel"><div class="lesson-contribution-list">${rows.map(row=>`<article class="lesson-contribution-card ${row.status}"><div><span class="eyebrow">${escape(row.meta.course?.name||'Curso')} • ${escape(row.meta.unit?.title||'Unit')}</span><h3>${escape(row.meta.lesson?.title||'Lesson')} • ${escape(row.stageLabel)}</h3><p>${escape(row.note)}</p><small>${escape(DEADLINE_LABELS[row.status]||DEADLINE_LABELS.on_track)} • ${fmtDateTime(row.updatedAt)} • ${escape(row.cycle?.reviewer||'Coordenação')}</small></div><div class="section-actions"><button class="btn primary small" onclick="PurpleLessonPlans.openLesson('${escape(row.lessonId)}')">Abrir aula</button>${can('lesson_plans.cycles.manage')?`<button class="btn ghost small" onclick="PurpleLessonPlans.markContributionDone('${escape(row.id)}')">Marcar pronta</button>`:''}</div></article>`).join('')||'<p class="muted">Nenhuma contribuição aberta neste momento.</p>'}</div></section></div>`}

  function openBookEditor(courseId){if(!can('lesson_plans.cycles.manage'))return toast('Cadastro de livro restrito à coordenação.');const course=findCourse(courseId),fit=coverFit(course);window.modal?.(`<div class="modal-head"><div><span class="eyebrow">Gerenciar livro</span><h3>${escape(course.name)}</h3></div><button class="modal-close" onclick="window.App.closeModal()">×</button></div><div class="lp-book-editor"><div class="lp-book-editor-preview"><div id="lpBookCoverPreview">${renderCover(course,'book-large')}</div><small id="lpBookUploadStatus">${course.coverUrl||course.coverStoragePath?'Capa real cadastrada':'Placeholder até a capa oficial ser associada'}</small><div class="lp-cover-controls"><label>Zoom da capa <input id="lpBookCoverZoom" type="range" min="80" max="180" value="${fit.zoom}" oninput="PurpleLessonPlans.previewBookCoverFit()"/></label><label>Horizontal <input id="lpBookCoverX" type="range" min="0" max="100" value="${fit.x}" oninput="PurpleLessonPlans.previewBookCoverFit()"/></label><label>Vertical <input id="lpBookCoverY" type="range" min="0" max="100" value="${fit.y}" oninput="PurpleLessonPlans.previewBookCoverFit()"/></label></div></div><div class="lp-book-editor-form"><div class="form-grid cols-2"><div class="field"><label>Nome</label><input id="lpBookName" value="${escape(course.name)}"/></div><div class="field"><label>Nível/faixa</label><input id="lpBookLevel" value="${escape(course.level||'')}"/></div></div><input id="lpBookCoverStoragePath" type="hidden" value="${escape(course.coverStoragePath||'')}"/><input id="lpBookPdfStoragePath" type="hidden" value="${escape(course.pdfStoragePath||'')}"/><div class="field"><label>URL segura da capa oficial</label><input id="lpBookCoverUrl" value="${escape(course.coverUrl||'')}" oninput="PurpleLessonPlans.previewBookCoverFit()" placeholder="https://.../discover-cover.png"/><small>Você pode colar uma URL segura ou selecionar uma imagem para upload.</small></div><div class="field"><label>URL segura do PDF do livro</label><input id="lpBookPdfUrl" value="${escape(course.pdfUrl||'')}" placeholder="https://.../discover.pdf"/><small>Ao subir PDF, salvamos também o caminho seguro e geramos um link novo ao abrir.</small></div><div class="lp-upload-drop"><b>Subir arquivos do livro</b><span>O botão envia para o Supabase Storage em <code>${escape(storageBucket())}</code> e associa o arquivo ao livro após salvar.</span><div class="lp-file-actions"><label><input id="lpBookCoverFile" type="file" accept="image/*" onchange="PurpleLessonPlans.uploadBookAsset('${escape(courseId)}','cover')"/>Subir capa</label><label><input id="lpBookPdfFile" type="file" accept="application/pdf" onchange="PurpleLessonPlans.uploadBookAsset('${escape(courseId)}','pdf')"/>Subir PDF</label></div></div><div class="field"><label>Descrição</label><textarea id="lpBookDescription">${escape(course.description||'')}</textarea></div><div class="field"><label>Informações pedagógicas</label><textarea id="lpBookPedagogicalInfo">${escape(course.pedagogicalInfo||'')}</textarea></div></div></div><div class="section-actions"><button class="btn ghost" onclick="window.App.closeModal()">Cancelar</button><button class="btn soft" onclick="PurpleLessonPlans.openCourse('${escape(courseId)}')">Ver livro</button><button id="lpBookSaveButton" class="btn primary" onclick="PurpleLessonPlans.saveBookEditor('${escape(courseId)}')">Salvar capa/PDF</button></div>`,true)}
  function previewBookCoverFit(){const url=document.getElementById('lpBookCoverUrl')?.value.trim()||'',x=Number(document.getElementById('lpBookCoverX')?.value||50),y=Number(document.getElementById('lpBookCoverY')?.value||50),zoom=Number(document.getElementById('lpBookCoverZoom')?.value||100),target=document.querySelector('#lpBookCoverPreview .lp-cover');if(!target)return;if(url){target.classList.remove('placeholder');target.innerHTML='';target.style.backgroundImage=`url('${url.replace(/'/g,'%27')}')`;target.style.backgroundPosition=`${x}% ${y}%`;target.style.backgroundSize=`${zoom}% auto`}else{target.removeAttribute('style')}}
  async function uploadBookAsset(courseId,type){const input=document.getElementById(type==='cover'?'lpBookCoverFile':'lpBookPdfFile'),file=input?.files?.[0],status=document.getElementById('lpBookUploadStatus');if(!file)return;try{if(status)status.textContent=`Enviando ${file.name}...`;if(type==='cover'){document.getElementById('lpBookCoverUrl').value=URL.createObjectURL(file);previewBookCoverFit()}const client=storageClient();if(!client?.storage?.from)throw new Error('Supabase Storage indisponível nesta sessão.');const ext=safeName(file.name).split('.').pop()||'',path=`books/${safeName(courseId)}/${type}-${Date.now()}${ext?'.'+ext:''}`,bucket=client.storage.from(storageBucket());const {error}=await bucket.upload(path,file,{cacheControl:'3600',upsert:true,contentType:file.type||undefined});if(error)throw error;const signed=await bucket.createSignedUrl(path,60*60*24*7),url=signed?.data?.signedUrl||bucket.getPublicUrl(path)?.data?.publicUrl;if(!url)throw new Error('Upload concluído, mas a URL de consulta não foi retornada.');document.getElementById(type==='cover'?'lpBookCoverUrl':'lpBookPdfUrl').value=url;document.getElementById(type==='cover'?'lpBookCoverStoragePath':'lpBookPdfStoragePath').value=path;if(type==='cover')previewBookCoverFit();if(status)status.textContent=type==='cover'?'Capa enviada. Ajuste o enquadramento e salve.':'PDF enviado. Clique em salvar para associar ao livro.';toast(type==='cover'?'Capa enviada.':'PDF enviado.')}catch(error){if(status)status.textContent=`Upload não concluído: ${error.message||error}`;toast(`Upload não concluído: ${error.message||error}`)}}
  async function saveBookEditor(courseId){const button=document.getElementById('lpBookSaveButton'),status=document.getElementById('lpBookUploadStatus');try{if(button){button.disabled=true;button.textContent='Salvando...'}const c=findCourse(courseId);c.name=document.getElementById('lpBookName')?.value.trim()||c.name;c.level=document.getElementById('lpBookLevel')?.value.trim()||'';c.coverUrl=document.getElementById('lpBookCoverUrl')?.value.trim()||'';c.pdfUrl=document.getElementById('lpBookPdfUrl')?.value.trim()||'';c.coverStoragePath=document.getElementById('lpBookCoverStoragePath')?.value.trim()||c.coverStoragePath||'';c.pdfStoragePath=document.getElementById('lpBookPdfStoragePath')?.value.trim()||c.pdfStoragePath||'';c.coverZoom=Number(document.getElementById('lpBookCoverZoom')?.value||100);c.coverPositionX=Number(document.getElementById('lpBookCoverX')?.value||50);c.coverPositionY=Number(document.getElementById('lpBookCoverY')?.value||50);c.description=document.getElementById('lpBookDescription')?.value.trim()||'';c.pedagogicalInfo=document.getElementById('lpBookPedagogicalInfo')?.value.trim()||'';await savePlan();window.App.closeModal();window.App.renderPage();toast('Livro atualizado.')}catch(error){console.error('Lesson Plans — erro ao salvar livro:',error);if(status)status.textContent=`Erro ao salvar: ${error.message||error}`;toast(`Erro ao salvar livro: ${error.message||error}`)}finally{if(button){button.disabled=false;button.textContent='Salvar capa/PDF'}}}
  async function saveLessonEditor(lessonId){if(!can('lesson_plans.edit'))return toast('Edição não autorizada.');const plan=findPlan(lessonId);for(const stage of LESSON_STAGES)Object.assign(plan.stages[stage.key],{objective:document.getElementById(`lpEdit-${stage.key}-objective`)?.value.trim()||'',activity:document.getElementById(`lpEdit-${stage.key}-activity`)?.value.trim()||'',instructions:document.getElementById(`lpEdit-${stage.key}-instructions`)?.value.trim()||'',observations:document.getElementById(`lpEdit-${stage.key}-observations`)?.value.trim()||'',duration:Number(document.getElementById(`lpEdit-${stage.key}-duration`)?.value||0),interaction:document.getElementById(`lpEdit-${stage.key}-interaction`)?.value.trim()||'',studentBookPages:document.getElementById(`lpEdit-${stage.key}-studentBookPages`)?.value.trim()||'',workbookPages:document.getElementById(`lpEdit-${stage.key}-workbookPages`)?.value.trim()||''});saveHistory(plan,'Atualizou Lesson Plan','Plano revisado no modo edição editorial.');bumpPlan(plan);await savePlan();openLesson(lessonId);toast('Lesson Plan salvo.')}
  function openResourceEditor(lessonId){if(!can('lesson_plans.edit'))return toast('Edição não autorizada.');window.modal?.(`<div class="modal-head"><div><span class="eyebrow">Adicionar recurso</span><h3>Link ou material da aula</h3></div><button class="modal-close" onclick="window.App.closeModal()">×</button></div><div class="lp-resource-editor"><div class="form-grid cols-2"><div class="field"><label>Título</label><input id="lpResourceTitle" placeholder="Ex.: Unit 01 Review"/></div><div class="field"><label>Tipo</label><select id="lpResourceType">${RESOURCE_TYPES.map(type=>`<option>${escape(type)}</option>`).join('')}</select></div><div class="field"><label>Link do recurso</label><input id="lpResourceUrl" placeholder="YouTube, Kahoot, Wordwall, PDF seguro..."/></div><div class="field"><label>Etapa relacionada</label><select id="lpResourceStage"><option value="general">Geral</option>${LESSON_STAGES.map(stage=>`<option value="${stage.key}">${escape(stage.label)}</option>`).join('')}</select></div></div><div class="field"><label>Descrição curta</label><textarea id="lpResourceDescription" placeholder="Uma frase para o professor entender quando usar."></textarea></div><div class="lp-upload-drop"><b>Arquivo da aula</b><span id="lpResourceUploadStatus">Para worksheets, PDFs, slides, áudio ou imagem. O botão tenta enviar para o Storage seguro e preencher o link automaticamente.</span><div class="lp-file-actions"><label><input id="lpResourceFile" type="file" accept=".pdf,.ppt,.pptx,.jpg,.jpeg,.png,.webp,.mp3,.wav,.m4a,.doc,.docx" onchange="PurpleLessonPlans.uploadResourceAsset('${escape(lessonId)}')"/>Subir arquivo</label></div></div></div><div class="section-actions"><button class="btn ghost" onclick="window.App.closeModal()">Cancelar</button><button class="btn primary" onclick="PurpleLessonPlans.saveResource('${escape(lessonId)}')">Adicionar à aula</button></div>`,true)}
  async function uploadResourceAsset(lessonId){const input=document.getElementById('lpResourceFile'),file=input?.files?.[0],status=document.getElementById('lpResourceUploadStatus');if(!file)return;try{if(status)status.textContent=`Enviando ${file.name}...`;const client=storageClient();if(!client?.storage?.from)throw new Error('Supabase Storage indisponível nesta sessão.');const path=`resources/${safeName(lessonId)}/${Date.now()}-${safeName(file.name)}`,bucket=client.storage.from(storageBucket());const {error}=await bucket.upload(path,file,{cacheControl:'3600',upsert:true,contentType:file.type||undefined});if(error)throw error;const signed=await bucket.createSignedUrl(path,60*60*24*7),url=signed?.data?.signedUrl||bucket.getPublicUrl(path)?.data?.publicUrl;if(!url)throw new Error('Upload concluído, mas a URL de consulta não foi retornada.');document.getElementById('lpResourceUrl').value=url;if(!document.getElementById('lpResourceTitle').value.trim())document.getElementById('lpResourceTitle').value=file.name.replace(/\.[^.]+$/,'');if(status)status.textContent='Arquivo enviado. Revise título/tipo e adicione à aula.';toast('Arquivo enviado.')}catch(error){if(status)status.textContent=`Upload não concluído: ${error.message||error}`;toast(`Upload não concluído: ${error.message||error}`)}}
  async function saveResource(lessonId){const plan=findPlan(lessonId);const title=document.getElementById('lpResourceTitle')?.value.trim()||'Recurso da aula',url=document.getElementById('lpResourceUrl')?.value.trim()||'';plan.resources.unshift({id:uid('res'),title,label:title,type:document.getElementById('lpResourceType')?.value||'Link',description:document.getElementById('lpResourceDescription')?.value.trim()||'',url,link:url,stageKey:document.getElementById('lpResourceStage')?.value||'general'});saveHistory(plan,'Adicionou recurso',`${userLabel(getUser()?.id)} adicionou ${title}.`);bumpPlan(plan);await savePlan();window.App.closeModal();window.App.renderPage();toast('Recurso adicionado.')}
  function openResource(id){const r=Object.values(ensureWorkspace().lessonPlans).flatMap(plan=>plan.resources||[]).find(item=>item.id===id);if(!r?.url)return toast('Recurso sem URL cadastrada.');const yt=youtubeId(r.url);if(yt)return window.modal?.(`<div class="modal-head"><div><span class="eyebrow">YouTube</span><h3>${escape(r.title)}</h3></div><button class="modal-close" onclick="window.App.closeModal()">×</button></div><div class="lp-video-frame"><iframe src="https://www.youtube.com/embed/${escape(yt)}" allowfullscreen></iframe></div>`,true);window.open(r.url,'_blank','noopener,noreferrer')}
  function openStageEditor(lessonId,stageKey){if(!can('lesson_plans.edit'))return toast('Edição não autorizada.');setEditMode(lessonId);requestAnimationFrame(()=>document.getElementById(`lpEdit-${stageKey}-objective`)?.focus())}
  async function saveStageEditor(lessonId,stageKey){const plan=findPlan(lessonId),expected=Number(document.getElementById('lpStageRevision')?.value||plan.revision||1);if(expected!==Number(plan.revision||1))return toast('Conflito de edição detectado. Reabra a seção antes de salvar.');Object.assign(plan.stages[stageKey],{objective:document.getElementById('lpStageObjective')?.value.trim()||'',activity:document.getElementById('lpStageActivity')?.value.trim()||'',instructions:document.getElementById('lpStageInstructions')?.value.trim()||'',observations:document.getElementById('lpStageObservations')?.value.trim()||'',duration:Number(document.getElementById('lpStageDuration')?.value||0),interaction:document.getElementById('lpStageInteraction')?.value||'Whole class',pages:document.getElementById('lpStagePages')?.value.trim()||'',studentBookPages:pagesFrom(document.getElementById('lpStagePages')?.value,'SB'),workbookPages:pagesFrom(document.getElementById('lpStagePages')?.value,'WB'),resources:csv(document.getElementById('lpStageResources')?.value),rapid:[...document.querySelectorAll('#lpStageRapid input:checked')].map(item=>item.value)});saveHistory(plan,`Atualizou ${stageKey}`,`Conteúdo pedagógico revisado em ${stageKey}.`);bumpPlan(plan);await savePlan();window.App.closeModal?.();window.App.renderPage()}
