  async function saveCycle(cycleId,courseId,unitId){const w=ensureWorkspace(),lessonIds=[...document.querySelectorAll('#lpCycleLessons input:checked')].map(i=>i.value),participantIds=[...document.querySelectorAll('#lpCycleParticipants input:checked')].map(i=>i.value);let cycle=findCycle(cycleId);if(!cycle){cycle={id:uid('cycle'),courseId,unitId,lessonIds:[],participantIds:[],status:'EM_CONSTRUCAO',progress:0,contributionStatus:'on_track'};w.cycles.unshift(cycle)}Object.assign(cycle,{title:document.getElementById('lpCycleTitle')?.value.trim()||cycle.title,deadline:document.getElementById('lpCycleDeadline')?.value||cycle.deadline,reviewer:document.getElementById('lpCycleReviewer')?.value.trim()||'Coordenação Pedagógica',scope:document.getElementById('lpCycleScope')?.value.trim()||'Aula específica',summary:document.getElementById('lpCycleSummary')?.value.trim()||'',lessonIds,participantIds,progress:Math.max(cycle.progress||0,25)});for(const id of lessonIds){const plan=findPlan(id);if(plan){plan.cycleId=cycle.id;if(plan.status==='A_MAPEAR')plan.status='EM_CONSTRUCAO';saveHistory(plan,cycleId?'Atualizou ciclo de planejamento':'Criou ciclo de planejamento',`${cycle.title} • prazo ${fmtDate(cycle.deadline)}.`);bumpPlan(plan)}}await savePlan();window.App.closeModal();window.App.renderPage()}
