  function printDocument(id){const m=findLessonMeta(id),p=findPlan(id),relations=(p.unitRelations||[]).map(rel=>{const unit=(m.course?.units||[]).find(item=>item.id===rel.unitId);return `${unit?.title||rel.unitId} ${unit?.theme?`— ${unit.theme}`:''} pp.${rel.pages}`}).join(' | ');return `<!doctype html><html><head><title>Purple Lesson Plan</title><style>body{font:14px/1.55 Georgia,serif;color:#24152f;margin:42px}h1,h2,h3{font-family:Arial,sans-serif;margin:.2em 0}header{border-bottom:3px solid #5c2383;padding-bottom:18px;margin-bottom:24px}.meta{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:16px 0}.meta div,section{border:1px solid #e5dced;border-radius:14px;padding:14px;margin:12px 0}dt{font-weight:bold;color:#5c2383}dd{margin:0 0 8px}.arc{background:#fbf7ff}</style></head><body><header><h3>PURPLE IDIOMAS</h3><h1>⭐ PLANO BASE PURPLE / R.A.P.I.D. LESSON PLAN</h1><p>${escape(m.course?.name)} • ${escape(p.curriculumId||'Curriculum')} • ${p.meetingNumber?`Meeting ${fmtNumber(p.meetingNumber)} • `:''}${escape(p.theme)}</p></header><div class="meta"><div><b>Unit(s)</b><br>${escape(relations||m.unit?.title)}</div><div><b>Páginas</b><br>${escape(p.bookPages||m.lesson?.bookPages||'—')}</div><div><b>Duração</b><br>${fmtNumber(p.duration)} min + 10 break</div><div><b>Status</b><br>${escape(workflowLabel(p.status))}</div></div><section><h2>Objetivo</h2><p>${escape(p.communicativeObjective)}</p><h2>Teacher Preparation</h2><p>${escape(p.teacherPreparation||'—')}</p><h2>R.A.P.I.D.</h2><p>${escape(p.rapidSummary||'—')}</p></section>${(p.meetingArcs||[]).map(arc=>`<section class="arc"><h2>${escape(arc.title)} — ${fmtNumber(arc.duration)} min</h2><p><b>Páginas:</b> ${escape(arc.pages)}</p><p>${escape(arc.objective)}</p><ul>${(arc.steps||[]).map(step=>`<li>${escape(step)}</li>`).join('')}</ul></section>`).join('')}${LESSON_STAGES.map(stage=>{const d=p.stages[stage.key]||{};return `<section><h2>${escape(stage.label)} — ${fmtNumber(d.duration||0)} min</h2><dl><dt>Objetivo</dt><dd>${escape(d.objective)}</dd><dt>Orientação</dt><dd>${escape(d.instructions)}</dd><dt>Atividade</dt><dd>${escape(d.activity)}</dd><dt>Páginas</dt><dd>Student Book ${escape(d.studentBookPages||'—')} • Workbook ${escape(d.workbookPages||'—')}</dd><dt>Teacher notes</dt><dd>${escape(d.observations)}</dd></dl></section>`}).join('')}<section><h2>Recursos relevantes</h2><ul>${(p.resources||[]).map(item=>`<li>${escape(item.type)} — ${escape(item.title||item.label)}: ${escape(item.description||'')}</li>`).join('')}</ul></section><section><h2>Ready / Mastery</h2><p>${escape(p.readyForNext||p.unitMastery||m.unit?.unitMastery||'—')}</p></section></body></html>`}
